def transform(grid):
 h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; centers=set()
 seeds=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==7]
 for sr,sc in seeds:
  for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
   r,c=sr,sc; bounced=False; seen=set()
   for _ in range(10*h*w):
    state=(r,c,dr,dc,bounced)
    if state in seen: break
    seen.add(state)
    if not 0<=r+dr<h: dr=-dr; bounced=True
    if not 0<=c+dc<w: dc=-dc; bounced=True
    r+=dr;c+=dc
    if not (0<=r<h and 0<=c<w): break
    out[r][c]=7
    if bounced and (r==sr or c==sc):
     centers.add((r,c));break
 for r,c in centers:
  for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
   if 0<=r+dr<h and 0<=c+dc<w: out[r+dr][c+dc]=3
 for r,c in centers: out[r][c]=1
 return out

